// kotlinx.coroutines: structured concurrency with a scope that bounds the lifetime.
suspend fun handle(id: String): Result = coroutineScope {   // children cannot outlive it
    val user   = async(Dispatchers.IO) { fetchUser(id) }     // concurrent child
    val orders = async(Dispatchers.IO) { fetchOrders(user.await()) }
    Result(user.await(), orders.await())   // coroutineScope cancels on first failure
}

// The alternative model - Java 21 virtual threads (stackful, no colouring):
try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    // ordinary BLOCKING code, but on a virtual thread: no async/sync split
    Future<Result> f = executor.submit(() -> handleBlocking(id));
    return f.get();
}
